function validate([floor, numCarpets, carpetLen]) {
  if (floor.length < 1 || floor.length > 1000) return 'floor needs 1 to 1000 tiles.';
  if (!/^[01]+$/.test(floor)) return "floor contains only '0' and '1'.";
  if (!Number.isInteger(numCarpets) || numCarpets < 1 || numCarpets > 1000) return 'numCarpets is an integer from 1 to 1000.';
  if (!Number.isInteger(carpetLen) || carpetLen < 1 || carpetLen > floor.length) return 'carpetLen is between 1 and floor.length.';
  return null;
}

