function minimumWhiteTiles(floor, numCarpets, carpetLen) {
  const n = floor.length;
  if (numCarpets * carpetLen >= n) {
    return 0;
  }
  const dp = Array.from({ length: numCarpets + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    dp[0][i] = dp[0][i - 1] + (floor[i - 1] === '1' ? 1 : 0);
  }
  for (let j = 1; j <= numCarpets; j++) {
    for (let i = 1; i <= n; i++) {
      const skip = dp[j][i - 1] + (floor[i - 1] === '1' ? 1 : 0);
      const cover = dp[j - 1][Math.max(0, i - carpetLen)];
      dp[j][i] = Math.min(skip, cover);
    }
  }
  return dp[numCarpets][n];
}

