function minimumWhiteTiles(floor, numCarpets, carpetLen) {
  // Try every set of distinct start positions; a carpet past the end or a repeated start never helps.
  const n = floor.length;
  const starts = n - carpetLen + 1;
  const covered = new Array(n).fill(0);
  let best = Infinity;
  const search = (start, left) => {
    if (start === starts || left === 0) {
      let visible = 0;
      for (let i = 0; i < n; i++) if (floor[i] === '1' && covered[i] === 0) visible++;
      best = Math.min(best, visible);
      return;
    }
    search(start + 1, left);
    for (let i = start; i < start + carpetLen; i++) covered[i]++;
    search(start + 1, left - 1);
    for (let i = start; i < start + carpetLen; i++) covered[i]--;
  };
  search(0, numCarpets);
  return best;
}

