function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const tiles = (n) => {
    const density = 0.2 + rand() * 0.6;
    let text = '';
    for (let i = 0; i < n; i++) text += rand() < density ? '1' : '0';
    return text;
  };
  if (size === 'small') {
    const n = pick(1, 10);
    const carpetLen = pick(1, Math.min(n, 4));
    const numCarpets = rand() < 0.9 ? pick(1, 4) : pick(1, 1000);
    return [tiles(n), numCarpets, carpetLen];
  }
  const n = 1000;
  const carpetLen = rand() < 0.3 ? pick(1, 3) : pick(4, 40);
  // Keep numCarpets * carpetLen below n so the table is actually filled.
  const numCarpets = pick(1, Math.floor((n - 1) / carpetLen));
  return [tiles(n), numCarpets, carpetLen];
}
